423	// AllocateNode allocates the podCIDRs for the given node. Returns a DeepCopied
424	// node with the podCIDRs allocated. In case there weren't CIDRs allocated
425	// the returned node will be nil.
426	// If allocated returns false, it means an update of CiliumNode Status should
427	// be performed into kubernetes as an error have happened while trying to
428	// allocate a CIDR for this node.
429	// Needs n.Mutex to be held.
430	func (n *NodesPodCIDRManager) allocateNode(node *v2.CiliumNode) (cn *v2.CiliumNode, allocated, updateStatus bool, err error) {
431		var cidrs *nodeCIDRs
432	
433		defer func() {
434			// Overwrite err value if we want to update the status of the
435			// cilium node into kubernetes.
436			if err != nil && updateStatus {
437				cn = node.DeepCopy()
438				cn.Status.IPAM.OperatorStatus.Error = err.Error()
439				err = nil
440				allocated = false
441			}
442		}()
443	
444		if len(node.Spec.IPAM.PodCIDRs) == 0 {
445			// If we can't allocate podCIDRs for now we should store the node
446			// temporarily until n.reSync is called.
447			if !n.canAllocatePodCIDRs {
448				n.logger.Debug("Postponing CIDR allocation", logfields.NodeName, node.Name)
449				n.nodesToAllocate[node.GetName()] = node
450				return nil, false, false, nil
451			}
452	
453			// Allocate the next free CIDRs
454			cidrs, allocated, err = n.allocateNext(node.GetName())
455			if err != nil {
456				// We want to log this error in cilium node
457				updateStatus = true
458				return
459			}
460	
461			n.logger.Debug(
462				"Allocated new CIDRs",
463				logfields.NodeName, node.Name,
464				logfields.CIDRs, cidrs,
465				logfields.Allocated, allocated,
466			)
467		} else {
468			cidrs, err = parsePodCIDRs(node.Spec.IPAM.PodCIDRs)
469			if err != nil {
470				// We want to log this error in cilium node
471				updateStatus = true
472				return
473			}
474			// Try to allocate the podCIDRs in the node, if there was a need
475			// for new CIDRs to be allocated the allocated returned value will be
476			// set to true.
477			cidrs, allocated, err = n.reuseIPNets(node.Name, cidrs.v4PodCIDRs, cidrs.v6PodCIDRs)
478			if err != nil {
479				// We want to log this error in cilium node
480				updateStatus = true
481				return
482			}
483			n.logger.Debug(
484				"Allocated existing CIDRs",
485				logfields.NodeName, node.Name,
486				logfields.CIDRs, cidrs,
487				logfields.Allocated, allocated,
488				logfields.CanAllocatePodCIDRs, n.canAllocatePodCIDRs,
489			)
490			if !allocated {
491				// If we can't allocate podCIDRs for now we should store the node
492				// temporarily until n.reSync is called.
493				if !n.canAllocatePodCIDRs {
494					n.nodesToAllocate[node.GetName()] = node
495					return nil, false, false, nil
496				}
497	
498				// no-op but still update the status to clear out a potential
499				// existing error.
500				if node.Status.IPAM.OperatorStatus.Error != "" {
501					cn = node.DeepCopy()
502					cn.Status.IPAM.OperatorStatus.Error = ""
503					updateStatus = true
504					return cn, false, updateStatus, nil
505				}
506				return nil, false, updateStatus, nil
507			}
508		}
509	
510		cn = node.DeepCopy()
511	
512		cn.Spec.IPAM.PodCIDRs = make([]string, 0, len(cidrs.v4PodCIDRs)+len(cidrs.v6PodCIDRs))
513	
514		for _, v4CIDR := range cidrs.v4PodCIDRs {
515			cn.Spec.IPAM.PodCIDRs = append(cn.Spec.IPAM.PodCIDRs, v4CIDR.String())
516		}
517		for _, v6CIDR := range cidrs.v6PodCIDRs {
518			cn.Spec.IPAM.PodCIDRs = append(cn.Spec.IPAM.PodCIDRs, v6CIDR.String())
519		}
520	
521		cn.Status.IPAM.OperatorStatus.Error = ""
522	
523		// UpdateStatus is explicitly set to false here because we want to update
524		// the entire node, not the status.
525		return cn, allocated, false, nil
526	}
