528	// syncNode adds the given node to the map of nodes that need to be synchronized
529	// with kubernetes and triggers a new resync.
530	// Needs n.Mutex to be held.
531	func (n *NodesPodCIDRManager) syncNode(op k8sOp, ciliumNode *v2.CiliumNode) {
532		n.ciliumNodesToK8s[ciliumNode.GetName()] = &ciliumNodeK8sOp{
533			ciliumNode: ciliumNode,
534			op:         op,
535		}
536		n.k8sReSync.Trigger()
537	}
