539	// releaseIPNets release the CIDRs allocated for this node.
540	// Returns true if the node was found in the allocator, false otherwise.
541	// Needs n.Mutex to be held.
542	func (n *NodesPodCIDRManager) releaseIPNets(nodeName string) bool {
543		cidrs, ok := n.nodes[nodeName]
544		if !ok {
545			return false
546		}
547	
548		delete(n.nodes, nodeName)
549	
550		n.releaseCIDRs(n.v4CIDRAllocators, cidrs.v4PodCIDRs)
551		n.releaseCIDRs(n.v6CIDRAllocators, cidrs.v6PodCIDRs)
552	
553		return true
554	}
