556	func (n *NodesPodCIDRManager) releaseCIDRs(cidrAllocators []cidralloc.CIDRAllocator, cidrsToRelease []*net.IPNet) {
557		if len(cidrAllocators) == 0 {
558			return
559		}
560		for _, ipNet := range cidrsToRelease {
561			for _, clusterCIDR := range cidrAllocators {
562				if !clusterCIDR.InRange(ipNet) {
563					continue
564				}
565				err := clusterCIDR.Release(ipNet)
566				if err != nil {
567					n.logger.Error("failed to release cidr",
568						logfields.Error, err,
569						logfields.CIDR, ipNet,
570					)
571					continue
572				}
573				n.logger.Info("node released CIDRs", logfields.CIDR, ipNet)
574				break
575			}
576		}
577	}
