335	// Upsert will re-allocate the node podCIDRs. In case the node already has
336	// podCIDRs allocated, the podCIDR allocator will try to allocate those CIDRs.
337	// In case the CIDRs were able to be allocated, the CiliumNode will have its
338	// podCIDRs fields set with the allocated CIDRs.
339	// In case the CIDRs were unable to be allocated, this function will return
340	// true and the node will have its status updated into kubernetes with the
341	// error message by the NodesPodCIDRManager.
342	func (n *NodesPodCIDRManager) Upsert(node *v2.CiliumNode) {
343		n.Mutex.Lock()
344		defer n.Mutex.Unlock()
345		n.upsertLocked(node)
346	}
