385	// Delete deletes the node from the allocator and releases the associated
386	// CIDRs of that node.
387	func (n *NodesPodCIDRManager) Delete(node *v2.CiliumNode) {
388		n.Mutex.Lock()
389		defer n.Mutex.Unlock()
390		if !n.canAllocatePodCIDRs {
391			delete(n.nodesToAllocate, node.Name)
392		}
393	
394		found := n.releaseIPNets(node.Name)
395		if !found {
396			return
397		}
398		// Mark the node to be deleted in k8s.
399		n.ciliumNodesToK8s[node.Name] = &ciliumNodeK8sOp{
400			op: k8sOpDelete,
401		}
402		n.k8sReSync.Trigger()
403	}
