405	// Resync resyncs the nodes with k8s.
406	func (n *NodesPodCIDRManager) Resync(context.Context, time.Time) {
407		n.Mutex.Lock()
408		if !n.canAllocatePodCIDRs {
409			n.canAllocatePodCIDRs = true
410			// Iterate over all nodes that we have kept stored up until Resync
411			// is called as now we are allowed to allocate podCIDRs for nodes
412			// without any podCIDR.
413			for _, cn := range n.nodesToAllocate {
414				n.upsertLocked(cn)
415			}
416			n.nodesToAllocate = nil
417		}
418		n.Mutex.Unlock()
419	
420		n.k8sReSync.Trigger()
421	}
