	// A successfully allocated family is only kept when the other family failed
	// solely due to its CIDR being already allocated by another node. Any other
	// failure (allocator full, allocator not found, ...) rolls back all state.
	hasOtherErr := (v4Err != nil && !isErrCIDRAllocated(v4Err)) ||
		(v6Err != nil && !isErrCIDRAllocated(v6Err))

	if allocated && err != nil && !hasOtherErr {
		// Partial conflict: at least one family was occupied while the other
		// conflicted with an already-allocated CIDR. Keep the successfully
		// occupied family. oldNodeCIDRs only contains the CIDRs for the
		// family/families that were allocated without conflict, so the
		// conflicting family is naturally omitted. Store the node so the
		// retained CIDRs stay occupied in the allocator pool. The non-nil error
		// still describes the conflicting family that was stripped.
		n.nodes[nodeName] = oldNodeCIDRs
		return oldNodeCIDRs, true, err
	}

	if err != nil {
		// Either no family was occupied or a non-conflict error occurred.
		// Revert any partial state (a failed allocateIPNet already reverts its
		// own work, so reverting a failed family is a no-op) and do not store
		// the node so that neither family remains occupied.
		if v4RevertFunc != nil {
			_ = v4RevertFunc()
		}
		if v6RevertFunc != nil {
			_ = v6RevertFunc()
		}
		return nil, false, err
	}

	// No error occurred. Store the node so its CIDRs stay occupied. Note that
	// allocated may be false here (e.g. a node re-requesting its existing
	// CIDRs), in which case oldNodeCIDRs already holds those CIDRs.
	n.nodes[nodeName] = oldNodeCIDRs

	return oldNodeCIDRs, allocated, nil
}

