func alloc(t *testing.T, alreadyAllocated bool) *mockCIDRAllocator {
	return &mockCIDRAllocator{
		OnInRange:     func(cidr *net.IPNet) bool { return true },
		OnIsFull:      func() bool { return false },
		OnIsAllocated: func(cidr *net.IPNet) (bool, error) { return alreadyAllocated, nil },
		OnOccupy:      func(cidr *net.IPNet) error { return nil },
		OnRelease:     func(cidr *net.IPNet) error { return nil },
	}
}

func TestScratchPartialConflictV4(t *testing.T) {
	// v4 already allocated elsewhere, v6 free -> keep v6 only.
	n := &NodesPodCIDRManager{
		logger:              hivetest.Logger(t),
		canAllocatePodCIDRs: true,
		v4CIDRAllocators:    []cidralloc.CIDRAllocator{alloc(t, true)},
		v6CIDRAllocators:    []cidralloc.CIDRAllocator{alloc(t, false)},
		nodes:               map[string]*nodeCIDRs{},
	}
	res, allocated, err := n.reuseIPNets("node-1", mustNewCIDRs("10.10.0.0/24"), mustNewCIDRs("fd00::/80"))
	require.True(t, allocated, "expected allocated=true on partial conflict")
	require.Error(t, err)
	require.Contains(t, err.Error(), "already allocated")
	require.Empty(t, res.v4PodCIDRs, "conflicting v4 must be omitted")
	require.Equal(t, mustNewCIDRs("fd00::/80"), res.v6PodCIDRs)
	require.Contains(t, n.nodes, "node-1")
	require.Empty(t, n.nodes["node-1"].v4PodCIDRs)
	require.Equal(t, mustNewCIDRs("fd00::/80"), n.nodes["node-1"].v6PodCIDRs)
}

func TestScratchPartialConflictV6(t *testing.T) {
	// v6 already allocated elsewhere, v4 free -> keep v4 only.
	n := &NodesPodCIDRManager{
		logger:              hivetest.Logger(t),
		canAllocatePodCIDRs: true,
		v4CIDRAllocators:    []cidralloc.CIDRAllocator{alloc(t, false)},
		v6CIDRAllocators:    []cidralloc.CIDRAllocator{alloc(t, true)},
		nodes:               map[string]*nodeCIDRs{},
	}
	res, allocated, err := n.reuseIPNets("node-1", mustNewCIDRs("10.10.0.0/24"), mustNewCIDRs("fd00::/80"))
	require.True(t, allocated)
	require.Error(t, err)
	require.True(t, strings.Contains(err.Error(), "already allocated"))
	require.Equal(t, mustNewCIDRs("10.10.0.0/24"), res.v4PodCIDRs)
	require.Empty(t, res.v6PodCIDRs)
	require.Equal(t, mustNewCIDRs("10.10.0.0/24"), n.nodes["node-1"].v4PodCIDRs)
	require.Empty(t, n.nodes["node-1"].v6PodCIDRs)
}

func TestScratchBothConflict(t *testing.T) {
	// both already allocated -> nothing kept, node not stored.
	n := &NodesPodCIDRManager{
		logger:              hivetest.Logger(t),
		canAllocatePodCIDRs: true,
		v4CIDRAllocators:    []cidralloc.CIDRAllocator{alloc(t, true)},
		v6CIDRAllocators:    []cidralloc.CIDRAllocator{alloc(t, true)},
		nodes:               map[string]*nodeCIDRs{},
	}
	res, allocated, err := n.reuseIPNets("node-1", mustNewCIDRs("10.10.0.0/24"), mustNewCIDRs("fd00::/80"))
	require.False(t, allocated)
	require.Error(t, err)
	require.Contains(t, err.Error(), "already allocated")
	require.Nil(t, res)
	require.NotContains(t, n.nodes, "node-1")
}
